/** When an event happens: days before today at a PKT minute-of-day, or minutes before now (today). */
export type DemoWhen = { d: number; m: number } | { ago: number };

export interface DemoLine {
  p: string;
  q?: number;
  v?: number;
}

export type DemoEvent =
  | { kind: "sale"; at: DemoWhen; customer?: string; lines: DemoLine[]; disc?: number; cash?: number }
  | { kind: "payment"; at: DemoWhen; customer: string; amount: number }
  | { kind: "purchase"; at: DemoWhen; supplier: string; lines: Array<{ p: string; q: number; cost: number }>; cash: number };

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

