/** Deterministic 25-day history: 14 dense days of cash sales + older udhaar so Pulse has real overdue rows. */
export function buildDemoHistory(): DemoEvent[] {
  const rnd = mulberry32(2026_11_24);
  const pick = <T,>(arr: T[]) => arr[Math.floor(rnd() * arr.length)];
  const ev: DemoEvent[] = [];

  // ---- older khata trail (FIFO overdue ages: Chhote Ali 18d, Ali Tailor 16d, Bilal 21d)
  ev.push({ kind: "sale", at: { d: 25, m: 600 }, customer: "CHHOTE_ALI", lines: [{ p: "ATTA", v: 36000 }, { p: "CHEENI", v: 24000 }], cash: 0 });
  // Bilal: 4,000 (24d) → paid 4,000 (21d) → 5,000 (21d) + 1,350 (10d) = 6,350, oldest unpaid 21d
  ev.push({ kind: "sale", at: { d: 24, m: 1100 }, customer: "BILAL", lines: [{ p: "DALDA", q: 5000 }, { p: "ATTA", v: 140000 }], cash: 0 });
  // Ali Tailor: 400 (23d) → paid 400 (16d) → 650 (16d)
  ev.push({ kind: "sale", at: { d: 23, m: 700 }, customer: "ALI_TAILOR", lines: [{ p: "CHEENI", v: 16000 }, { p: "PATTI", v: 24000 }], cash: 0 });
  ev.push({ kind: "payment", at: { d: 21, m: 1140 }, customer: "BILAL", amount: 400000 });
  ev.push({ kind: "sale", at: { d: 21, m: 1150 }, customer: "BILAL", lines: [{ p: "GHEE", q: 2 }, { p: "ATTA", v: 388000 }], cash: 0 });
  // Ali Driver: 400 (20d) → paid 400 (2d) = 0
  ev.push({ kind: "sale", at: { d: 20, m: 840 }, customer: "ALI_DRIVER", lines: [{ p: "DOODH", q: 1000 }, { p: "BREAD", q: 1 }, { p: "BISCUIT", q: 1 }], cash: 0 });
  // Chhote Ali: 600 (25d) → paid 600 (18d) → 900 (18d) + 500 (9d) = 1,400, oldest unpaid 18d
  ev.push({ kind: "payment", at: { d: 18, m: 1080 }, customer: "CHHOTE_ALI", amount: 60000 });
  ev.push({ kind: "sale", at: { d: 18, m: 1090 }, customer: "CHHOTE_ALI", lines: [{ p: "ATTA", v: 60000 }, { p: "DAAL_CHANA", v: 30000 }], cash: 0 });
  ev.push({ kind: "payment", at: { d: 16, m: 1000 }, customer: "ALI_TAILOR", amount: 40000 });
  ev.push({ kind: "sale", at: { d: 16, m: 1010 }, customer: "ALI_TAILOR", lines: [{ p: "CHAWAL", v: 38000 }, { p: "SABUN", q: 2 }, { p: "BISCUIT", v: 7000 }], cash: 0 });
  ev.push({ kind: "sale", at: { d: 10, m: 1200 }, customer: "BILAL", lines: [{ p: "CHEENI", v: 135000 }], cash: 0 });
  ev.push({ kind: "sale", at: { d: 9, m: 900 }, customer: "CHHOTE_ALI", lines: [{ p: "CHEENI", v: 32000 }, { p: "PATTI", v: 18000 }], cash: 0 });
  // Tariq Butt: 3,500 bill, 1,000 cash (8d) → paid 2,500 (1d) = 0
  ev.push({ kind: "sale", at: { d: 8, m: 650 }, customer: "TARIQ_B", lines: [{ p: "PATTI", q: 1000 }, { p: "CHEENI", q: 5000 }, { p: "DOODH", q: 5000 }], cash: 100000 });
  ev.push({ kind: "payment", at: { d: 1, m: 1180 }, customer: "TARIQ_B", amount: 250000 });
  ev.push({ kind: "payment", at: { d: 2, m: 600 }, customer: "ALI_DRIVER", amount: 40000 });

  // ---- wholesale restocks (record_purchase)
  ev.push({ kind: "purchase", at: { d: 12, m: 560 }, supplier: "Al-Madina Wholesale", lines: [{ p: "ATTA", q: 40000, cost: 432000 }, { p: "CHAWAL", q: 10000, cost: 340000 }, { p: "SURF", q: 10, cost: 480000 }], cash: 1252000 });
  ev.push({ kind: "purchase", at: { d: 6, m: 545 }, supplier: "Punjab Cash & Carry", lines: [{ p: "CHEENI", q: 10000, cost: 148000 }, { p: "DALDA", q: 15000, cost: 735000 }], cash: 500000 });

  // ---- 14 dense days of walk-in cash sales
  for (let d = 13; d >= 1; d--) {
    const n = 8 + Math.floor(rnd() * 7);
    for (let i = 0; i < n; i++) {
      const m = 480 + Math.floor((i / n) * 840) + Math.floor(rnd() * 40);
      const lines: DemoLine[] = [];
      const k = 1 + Math.floor(rnd() * 3);
      for (let j = 0; j < k; j++) {
        const [p, qs] = pick(CASH_BASKET);
        if (!lines.some((l) => l.p === p)) lines.push({ p, q: pick(qs) });
      }
      ev.push({ kind: "sale", at: { d, m }, lines });
    }
    // steady velocity for the two stockout items (≈2kg cheeni/day, ≈1 tin dalda/day in the last week)
    if (d <= 7) {
      for (const q of [500, 750, 375, 375]) ev.push({ kind: "sale", at: { d, m: 500 + q }, lines: [{ p: "CHEENI", q }] });
      ev.push({ kind: "sale", at: { d, m: 1130 }, lines: [{ p: "DALDA", q: 5000 }] });
    }
  }

  // ---- today (relative to reset time) — 22 walk-ins + 1 udhaar so both pulse cards are alive
  for (let i = 0; i < 22; i++) {
    const lines: DemoLine[] = [];
    const k = 1 + Math.floor(rnd() * 3);
    for (let j = 0; j < k; j++) {
      const [p, qs] = pick(CASH_BASKET);
      if (!lines.some((l) => l.p === p)) lines.push({ p, q: pick(qs) });
    }
    ev.push({ kind: "sale", at: { ago: 190 - i * 8 }, lines });
  }
  ev.push({ kind: "sale", at: { ago: 25 }, customer: "TARIQ_M", lines: [{ p: "ATTA", q: 5000 }, { p: "CHEENI", q: 1000 }, { p: "DOODH", v: 14000 }], cash: 0 });

  return sortEvents(ev);
}

function sortEvents(ev: DemoEvent[]): DemoEvent[] {
  // chronological: older days first; today's "ago" events last
  return [...ev].sort((a, b) => absMinutes(a.at) - absMinutes(b.at));
}

function absMinutes(w: DemoWhen): number {
  return "ago" in w ? 100 * 1440 - w.ago : (100 - w.d) * 1440 + w.m - 1440;
}
